        while index < len(text):
            end = index + 1
            if unicodedata.category(text[index]).startswith("L"):
                while end < len(text) and unicodedata.category(text[end]).startswith("M"):
                    end += 1
            characters.append(text[index:end])
            index = end
    counts = {}
    for character in characters:
        counts[character] = counts.get(character, 0) + 1
    return next((character for character in characters if counts[character] == 1), None)

